/**
 * Regenerates NARRATION-CHECKLIST.md at the repo root — the human-readable
 * ledger of the narration shelf, Modernity-checklist style. Do not edit the
 * checklist by hand; this script is the only writer.
 *
 *   node scripts/narration/build-narration-checklist.mjs
 */
import { readFileSync, writeFileSync, readdirSync, existsSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(HERE, '..', '..');
const WORK = path.join(HERE, 'work');
const VOICES = JSON.parse(readFileSync(path.join(HERE, 'voices.json'), 'utf8'));
const personas = Object.keys(VOICES.personas);

// The pilot shelf (docs/narration-plan.md §5). Grows deliberately; a book
// belongs here once Michael decides it gets narration, not once it succeeds.
const SHELF = ['84', '1342', '14838'];

const lines = [];
lines.push('# Narration checklist');
lines.push('');
lines.push('Generated by `node scripts/narration/build-narration-checklist.mjs` — do not edit by hand.');
lines.push('The pipeline and run order live in `docs/narration-plan.md` §13.');
lines.push('');

let done = 0;
let total = 0;
const rows = [];
const excluded = [];
const ids = new Set(SHELF);
if (existsSync(WORK)) for (const d of readdirSync(WORK)) if (/^\d+$/.test(d)) ids.add(d);

for (const id of [...ids].sort((a, b) => Number(a) - Number(b))) {
    const exPath = path.join(WORK, id, 'excluded.json');
    if (existsSync(exPath)) {
        const ex = JSON.parse(readFileSync(exPath, 'utf8'));
        excluded.push(`- ${id} — ${ex.reason}: token ${ex.hits[0].token} \`${ex.hits[0].word}\` (${ex.hits.length} hit(s))`);
        continue;
    }
    const marks = personas.map((p) => {
        total++;
        const statusPath = path.join(WORK, id, p, 'status.json');
        if (!existsSync(statusPath)) return `☐ ${p}`;
        const s = JSON.parse(readFileSync(statusPath, 'utf8'));
        if (s.ok) { done++; return `☑ ${p}`; }
        return `✗ ${p} (${(s.error || 'failed').slice(0, 60)})`;
    });
    rows.push(`- ${id}: ${marks.join('  ')}`);
}

lines.push(`**${done} / ${total}** book×voice pairs finished.`);
lines.push('');
lines.push(...rows);
if (excluded.length) {
    lines.push('');
    lines.push('## Excluded by the leftover gate (not narratable until a coordinated re-strip + re-anchor)');
    lines.push(...excluded);
}
lines.push('');

writeFileSync(path.join(ROOT, 'NARRATION-CHECKLIST.md'), lines.join('\n'));
console.log(`NARRATION-CHECKLIST.md regenerated (${done}/${total} done, ${excluded.length} excluded).`);
